create function public.consume_assistant_request(p_user uuid) returns boolean language plpgsql security invoker set search_path='' as $$ declare n integer; begin insert into public.assistant_usage(user_id,bucket,requests) values(p_user,date_trunc('hour',now()),1) on conflict(user_id,bucket) do update set requests=assistant_usage.requests+1 returning requests into n; return n<=30; end $$; revoke all on function public.consume_assistant_request(uuid) from public,anon,authenticated; grant execute on function public.consume_assistant_request(uuid) to service_role;
